      (STOREID, ANIMALID, PRICE, CREATEDBY, CREATEDDATE, UPDATEDBY,
       UPDATEDDATE)
      SELECT
        L1.STOREID,
        L3.ANIMALID,
        2.95,
        'YBTKS',
        '2026-10-25-15.39.44.931979',
        'YBTKS',
        '2026-10-26-08.31.53.184111'
      FROM PETD1.TBPET002 L1,
           PETD1.TBPET006 L3
      WHERE L1.STORECODE = 'PS000014'
        AND L3.STOREID = L1.STOREID
        AND L3.ANIMALTYPE = 'FISH'
        AND L3.ANIMALRACE = 'GOLDFISH'
        AND L3.ANIMALNAME = 'Goldfish';

